-- Load cleaned Olist data into MySQL.\n-- Replace <PROJECT_ROOT> with your local repository path before running.\n-- Do not commit machine-specific absolute paths or database credentials.\n\nLOAD DATA INFILE '<PROJECT_ROOT>/data/cleaned/orders_cleaned.csv'\nINTO TABLE orders\nFIELDS TERMINATED BY ','\nOPTIONALLY ENCLOSED BY '"'\nLINES TERMINATED BY '\\n'\nIGNORE 1 LINES\n(\n    order_id,\n    customer_id,\n    order_status,\n    @order_purchase_timestamp,\n    @order_approved_at,\n    @order_delivered_carrier_date,\n    @order_delivered_customer_date,\n    @order_estimated_delivery_date\n)\nSET\n    order_purchase_timestamp = NULLIF(@order_purchase_timestamp, ''),\n    order_approved_at = NULLIF(@order_approved_at, ''),\n    order_delivered_carrier_date = NULLIF(@order_delivered_carrier_date, ''),\n    order_delivered_customer_date = NULLIF(@order_delivered_customer_date, ''),\n    order_estimated_delivery_date = NULLIF(@order_estimated_delivery_date, '');\n